<script setup>
import {computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,Settings,AudioLines,Play,X} from 'lucide-vue-next'
import {state,bootstrap,play} from './state'
import {connection,data,rpc} from './transport'
import {speech,stopVoice,interruptResponse,unlockAudio} from './speech'
const route=useRoute(),router=useRouter(),isHome=computed(()=>route.path==='/')
const computeLabel=computed(()=>({gpu:'GPU text model · CPU speech',hybrid:'GPU/CPU text model · CPU speech',cpu:'CPU processing',standby:'Text model on standby'}[data(state.models.find(m=>m.id==='qwen')||{}).device]||'Loading models'))
const backTarget=computed(()=>['moon','system'].includes(route.query.from)?{path:'/lcc/'+route.query.from,query:{component:route.query.component||''}}:'/')
const backLabel=computed(()=>route.query.from==='moon'?'Back to Moon simulation':route.query.from==='system'?'Back to integrated system':'Back to overview')
let modelTimer
const navigation={nav_machine:'/machines/valve-leak-test',nav_dashboard:'/',nav_protocols:'/protocols',nav_knowledge:'/knowledge',nav_voice:'/admin/voices'}
function action(e){const key=e.detail;if(navigation[key])router.push(navigation[key]);else if(key.startsWith('machine_')){if(route.path!=='/machines/valve-leak-test'){state.pendingAction=key;router.push('/machines/valve-leak-test')}else state.pendingAction=key}}
onMounted(()=>{bootstrap();window.addEventListener('shopfloor-action',action);modelTimer=setInterval(()=>{if(!state.models.length||state.models.some(m=>m.state==='loading'))rpc('bootstrap').then(r=>state.models=r.rows||[]).catch(()=>{})},2000)})
onUnmounted(()=>{clearInterval(modelTimer);stopVoice();window.removeEventListener('shopfloor-action',action)})
</script>
<template><div class="app-shell lcc-shell"><header class="app-header"><RouterLink to="/" class="brand lcc-brand" aria-label="Back to overview"><span class="lcc-brand-mark">LCC</span>Lunar Charge Control</RouterLink><div class="header-center">DEVELOPMENT <span>/</span> VIRTUAL TEST BENCHES</div><div class="header-actions"><span class="environment">Local simulation</span><RouterLink to="/admin" class="icon-button" title="Administration"><Settings :size="20"/></RouterLink><span class="identity" title="Local demo identity">D</span></div></header><main class="surface"><div v-if="!isHome" class="surface-top"><RouterLink :to="backTarget" class="back"><ArrowLeft :size="16"/> {{backLabel}}</RouterLink><span class="surface-label">{{route.meta.title}}</span></div><RouterView v-slot="{Component}"><KeepAlive include="Machine"><component :is="Component" class="route-surface"/></KeepAlive></RouterView></main><div v-if="state.notice" role="status" class="toast">{{state.notice}}<button @click="state.notice=''" aria-label="Dismiss notification"><X :size="16"/></button></div><button v-if="state.audioBlocked&&state.lastAudio" class="enable-audio" @click="play(state.lastAudio.bytes,state.lastAudio.tid,state.lastAudio.audioId)"><Play :size="16"/> Play spoken response</button><button v-if="speech.blocked" class="enable-audio" @click="unlockAudio"><Play :size="16"/> Enable speech playback</button><footer class="app-footer"><span v-if="speech.listening" class="footer-speech">Microphone active <button @click="interruptResponse">Stop response</button><button @click="stopVoice">End voice mode</button></span><span v-else-if="speech.playing" class="footer-speech">Sprachausgabe <button @click="interruptResponse">Interrupt</button></span><span v-else>LUNAR CHARGE CONTROL / SIMULATION</span><span>{{connection.state==='connected'?'Connected':'Connecting'}} · {{route.meta.lunar?'Local SI simulation engine':computeLabel}}</span></footer></div></template>
